    { const char * tb_v1833 = "    work(job);\n"; *(const char * *)tb_grow(v_lines) = tb_v1833; }
    { const char * tb_v1834 = "    for (int i = 1; i < n; i++) pthread_join(t[i], 0);\n"; *(const char * *)tb_grow(v_lines) = tb_v1834; }
