    { const char * tb_v2077 = "// CGBitmapContextCreateImage делал копию при записи: каждая новая точка в кадре\n"; *(const char * *)tb_grow(v_lines) = tb_v2077; }
    { const char * tb_v2078 = "// стоила копии страницы памяти. Теперь три своих буфера по кругу: кадр копируется\n"; *(const char * *)tb_grow(v_lines) = tb_v2078; }
