    { const char * tb_v2298 = "# Нужен, чтобы tachbit bare работал без ld.lld (на Mac его не всегда можно поставить).\n"; *(const char * *)tb_grow(v_lines) = tb_v2298; }
    { const char * tb_v2299 = "# Раскладка та же, что в файле сборки компилятора:\n"; *(const char * *)tb_grow(v_lines) = tb_v2299; }
    { const char * tb_v2300 = "#   1 МБ: .multiboot, код, константы  (только чтение)\n"; *(const char * *)tb_grow(v_lines) = tb_v2300; }
    { const char * tb_v2301 = "#   данные, .tbtls (переменные потока подряд), .bss\n"; *(const char * *)tb_grow(v_lines) = tb_v2301; }
    { const char * tb_v2302 = "#   с границы 4 МБ: .tbheap (куча, в файл не пишется)\n"; *(const char * *)tb_grow(v_lines) = tb_v2302; }
    { const char * tb_v2303 = "# Запуск:  python3 elf_link.py вход.o выход.elf      (лишние -m/-T для совместимости с ld пропускаются)\n"; *(const char * *)tb_grow(v_lines) = tb_v2303; }
    { const char * tb_v2304 = "import struct\n"; *(const char * *)tb_grow(v_lines) = tb_v2304; }
    { const char * tb_v2305 = "import sys\n"; *(const char * *)tb_grow(v_lines) = tb_v2305; }
    { const char * tb_v2306 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v2306; }
    { const char * tb_v2307 = "R_386_NONE, R_386_32, R_386_PC32 = 0, 1, 2\n"; *(const char * *)tb_grow(v_lines) = tb_v2307; }
    { const char * tb_v2308 = "SHT_PROGBITS, SHT_SYMTAB, SHT_NOBITS, SHT_REL, SHT_RELA = 1, 2, 8, 9, 4\n"; *(const char * *)tb_grow(v_lines) = tb_v2308; }
    { const char * tb_v2309 = "SHF_WRITE, SHF_ALLOC, SHF_EXEC = 1, 2, 4\n"; *(const char * *)tb_grow(v_lines) = tb_v2309; }
    { const char * tb_v2310 = "SHN_UNDEF, SHN_ABS, SHN_COMMON = 0, 0xFFF1, 0xFFF2\n"; *(const char * *)tb_grow(v_lines) = tb_v2310; }
    { const char * tb_v2311 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v2311; }
    { const char * tb_v2312 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v2312; }
    { const char * tb_v2313 = "def fail(msg):\n"; *(const char * *)tb_grow(v_lines) = tb_v2313; }
    { const char * tb_v2314 = "    sys.stderr.write(\"компоновка ядра: \" + msg + \"\\n\")\n"; *(const char * *)tb_grow(v_lines) = tb_v2314; }
    { const char * tb_v2315 = "    sys.exit(1)\n"; *(const char * *)tb_grow(v_lines) = tb_v2315; }
    { const char * tb_v2316 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v2316; }
    { const char * tb_v2317 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v2317; }
    { const char * tb_v2318 = "def align(x, a):\n"; *(const char * *)tb_grow(v_lines) = tb_v2318; }
    { const char * tb_v2319 = "    return x if a <= 1 else (x + a - 1) // a * a\n"; *(const char * *)tb_grow(v_lines) = tb_v2319; }
    { const char * tb_v2320 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v2320; }
    { const char * tb_v2321 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v2321; }
    { const char * tb_v2322 = "def main(argv):\n"; *(const char * *)tb_grow(v_lines) = tb_v2322; }
    { const char * tb_v2323 = "    files = []\n"; *(const char * *)tb_grow(v_lines) = tb_v2323; }
    { const char * tb_v2324 = "    i = 1\n"; *(const char * *)tb_grow(v_lines) = tb_v2324; }
    { const char * tb_v2325 = "    while i < len(argv):\n"; *(const char * *)tb_grow(v_lines) = tb_v2325; }
    { const char * tb_v2326 = "        a = argv[i]\n"; *(const char * *)tb_grow(v_lines) = tb_v2326; }
    { const char * tb_v2327 = "        if a in (\"-m\", \"-T\"):\n"; *(const char * *)tb_grow(v_lines) = tb_v2327; }
    { const char * tb_v2328 = "            i += 2\n"; *(const char * *)tb_grow(v_lines) = tb_v2328; }
    { const char * tb_v2329 = "            continue\n"; *(const char * *)tb_grow(v_lines) = tb_v2329; }
    { const char * tb_v2330 = "        if a == \"-o\":\n"; *(const char * *)tb_grow(v_lines) = tb_v2330; }
    { const char * tb_v2331 = "            files.append((\"out\", argv[i + 1]))\n"; *(const char * *)tb_grow(v_lines) = tb_v2331; }
    { const char * tb_v2332 = "            i += 2\n"; *(const char * *)tb_grow(v_lines) = tb_v2332; }
    { const char * tb_v2333 = "            continue\n"; *(const char * *)tb_grow(v_lines) = tb_v2333; }
    { const char * tb_v2334 = "        files.append((\"in\", a))\n"; *(const char * *)tb_grow(v_lines) = tb_v2334; }
    { const char * tb_v2335 = "        i += 1\n"; *(const char * *)tb_grow(v_lines) = tb_v2335; }
    { const char * tb_v2336 = "    ins = [f for k, f in files if k == \"in\"]\n"; *(const char * *)tb_grow(v_lines) = tb_v2336; }
    { const char * tb_v2337 = "    outs = [f for k, f in files if k == \"out\"]\n"; *(const char * *)tb_grow(v_lines) = tb_v2337; }
    { const char * tb_v2338 = "    if len(outs) == 1 and len(ins) == 1:\n"; *(const char * *)tb_grow(v_lines) = tb_v2338; }
    { const char * tb_v2339 = "        src, dst = ins[0], outs[0]\n"; *(const char * *)tb_grow(v_lines) = tb_v2339; }
    { const char * tb_v2340 = "    elif not outs and len(ins) == 2:\n"; *(const char * *)tb_grow(v_lines) = tb_v2340; }
    { const char * tb_v2341 = "        src, dst = ins\n"; *(const char * *)tb_grow(v_lines) = tb_v2341; }
    { const char * tb_v2342 = "    else:\n"; *(const char * *)tb_grow(v_lines) = tb_v2342; }
    { const char * tb_v2343 = "        fail(\"нужно: elf_link.py вход.o -o выход.elf\")\n"; *(const char * *)tb_grow(v_lines) = tb_v2343; }
    { const char * tb_v2344 = "    data = open(src, \"rb\").read()\n"; *(const char * *)tb_grow(v_lines) = tb_v2344; }
    { const char * tb_v2345 = "    if data[:4] != b\"\\x7fELF\" or data[4] != 1 or data[5] != 1:\n"; *(const char * *)tb_grow(v_lines) = tb_v2345; }
    { const char * tb_v2346 = "        fail(\"вход — не 32-битный ELF\")\n"; *(const char * *)tb_grow(v_lines) = tb_v2346; }
    { const char * tb_v2347 = "    (e_type, e_machine) = struct.unpack_from(\"<HH\", data, 16)\n"; *(const char * *)tb_grow(v_lines) = tb_v2347; }
    { const char * tb_v2348 = "    if e_type != 1 or e_machine != 3:\n"; *(const char * *)tb_grow(v_lines) = tb_v2348; }
    { const char * tb_v2349 = "        fail(\"вход — не объектный файл i386\")\n"; *(const char * *)tb_grow(v_lines) = tb_v2349; }
    { const char * tb_v2350 = "    e_shoff, = struct.unpack_from(\"<I\", data, 32)\n"; *(const char * *)tb_grow(v_lines) = tb_v2350; }
    { const char * tb_v2351 = "    e_shentsize, e_shnum, e_shstrndx = struct.unpack_from(\"<HHH\", data, 46)\n"; *(const char * *)tb_grow(v_lines) = tb_v2351; }
    { const char * tb_v2352 = "    secs = []\n"; *(const char * *)tb_grow(v_lines) = tb_v2352; }
    { const char * tb_v2353 = "    for k in range(e_shnum):\n"; *(const char * *)tb_grow(v_lines) = tb_v2353; }
    { const char * tb_v2354 = "        name, typ, flags, addr, off, size, link, info, al, entsize = struct.unpack_from(\"<10I\", data, e_shoff + k * e_shentsize)\n"; *(const char * *)tb_grow(v_lines) = tb_v2354; }
    { const char * tb_v2355 = "        secs.append(dict(name=name, type=typ, flags=flags, off=off, size=size, link=link, info=info, align=max(al, 1), addr=None))\n"; *(const char * *)tb_grow(v_lines) = tb_v2355; }
    { const char * tb_v2356 = "    strtab = secs[e_shstrndx]\n"; *(const char * *)tb_grow(v_lines) = tb_v2356; }
    { const char * tb_v2357 = "    for s in secs:\n"; *(const char * *)tb_grow(v_lines) = tb_v2357; }
    { const char * tb_v2358 = "        end = data.index(b\"\\0\", strtab[\"off\"] + s[\"name\"])\n"; *(const char * *)tb_grow(v_lines) = tb_v2358; }
    { const char * tb_v2359 = "        s[\"name\"] = data[strtab[\"off\"] + s[\"name\"]:end].decode()\n"; *(const char * *)tb_grow(v_lines) = tb_v2359; }
    { const char * tb_v2360 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v2360; }
    { const char * tb_v2361 = "    # группы по порядку раскладки\n"; *(const char * *)tb_grow(v_lines) = tb_v2361; }
    { const char * tb_v2362 = "    def group(s):\n"; *(const char * *)tb_grow(v_lines) = tb_v2362; }
    { const char * tb_v2363 = "        n = s[\"name\"]\n"; *(const char * *)tb_grow(v_lines) = tb_v2363; }
    { const char * tb_v2364 = "        if n == \".multiboot\":\n"; *(const char * *)tb_grow(v_lines) = tb_v2364; }
    { const char * tb_v2365 = "            return 0\n"; *(const char * *)tb_grow(v_lines) = tb_v2365; }
    { const char * tb_v2366 = "        if n == \".tbheap\":\n"; *(const char * *)tb_grow(v_lines) = tb_v2366; }
    { const char * tb_v2367 = "            return 6\n"; *(const char * *)tb_grow(v_lines) = tb_v2367; }
    { const char * tb_v2368 = "        if n == \".tbtls\":\n"; *(const char * *)tb_grow(v_lines) = tb_v2368; }
    { const char * tb_v2369 = "            return 4\n"; *(const char * *)tb_grow(v_lines) = tb_v2369; }
    { const char * tb_v2370 = "        if s[\"flags\"] & SHF_EXEC:\n"; *(const char * *)tb_grow(v_lines) = tb_v2370; }
    { const char * tb_v2371 = "            return 1\n"; *(const char * *)tb_grow(v_lines) = tb_v2371; }
    { const char * tb_v2372 = "        if not (s[\"flags\"] & SHF_WRITE):\n"; *(const char * *)tb_grow(v_lines) = tb_v2372; }
    { const char * tb_v2373 = "            return 2\n"; *(const char * *)tb_grow(v_lines) = tb_v2373; }
    { const char * tb_v2374 = "        if s[\"type\"] == SHT_NOBITS:\n"; *(const char * *)tb_grow(v_lines) = tb_v2374; }
    { const char * tb_v2375 = "            return 5\n"; *(const char * *)tb_grow(v_lines) = tb_v2375; }
    { const char * tb_v2376 = "        return 3\n"; *(const char * *)tb_grow(v_lines) = tb_v2376; }
    { const char * tb_v2377 = "    alloc = [k for k, s in enumerate(secs) if s[\"flags\"] & SHF_ALLOC and s[\"type\"] in (SHT_PROGBITS, SHT_NOBITS) and s[\"size\"] > 0]\n"; *(const char * *)tb_grow(v_lines) = tb_v2377; }
    { const char * tb_v2378 = "    order = sorted(alloc, key=lambda k: (group(secs[k]), k))\n"; *(const char * *)tb_grow(v_lines) = tb_v2378; }
    { const char * tb_v2379 = "\n"; *(const char * *)tb_grow(v_lines) = tb_v2379; }
    { const char * tb_v2380 = "    syms_extra = {}\n"; *(const char * *)tb_grow(v_lines) = tb_v2380; }
    { const char * tb_v2381 = "    addr = 0x100000\n"; *(const char * *)tb_grow(v_lines) = tb_v2381; }
    { const char * tb_v2382 = "    syms_extra[\"tb_code_start\"] = addr\n"; *(const char * *)tb_grow(v_lines) = tb_v2382; }
    { const char * tb_v2383 = "    syms_extra[\"tb_kernel_end\"] = 0\n"; *(const char * *)tb_grow(v_lines) = tb_v2383; }
    { const char * tb_v2384 = "    common_size = 0\n"; *(const char * *)tb_grow(v_lines) = tb_v2384; }
    { const char * tb_v2385 = "    placed = {}\n"; *(const char * *)tb_grow(v_lines) = tb_v2385; }
    { const char * tb_v2386 = "    for g in range(7):\n"; *(const char * *)tb_grow(v_lines) = tb_v2386; }
    { const char * tb_v2387 = "        if g == 3:\n"; *(const char * *)tb_grow(v_lines) = tb_v2387; }
    { const char * tb_v2388 = "            addr = align(addr, 4096)\n"; *(const char * *)tb_grow(v_lines) = tb_v2388; }
    { const char * tb_v2389 = "            syms_extra[\"tb_code_end\"] = addr\n"; *(const char * *)tb_grow(v_lines) = tb_v2389; }
    { const char * tb_v2390 = "        if g == 4:\n"; *(const char * *)tb_grow(v_lines) = tb_v2390; }
    { const char * tb_v2391 = "            syms_extra[\"tb_tls_start\"] = addr\n"; *(const char * *)tb_grow(v_lines) = tb_v2391; }
    { const char * tb_v2392 = "        if g == 5:\n"; *(const char * *)tb_grow(v_lines) = tb_v2392; }
    { const char * tb_v2393 = "            syms_extra[\"tb_tls_end\"] = addr\n"; *(const char * *)tb_grow(v_lines) = tb_v2393; }
    { const char * tb_v2394 = "        if g == 6:\n"; *(const char * *)tb_grow(v_lines) = tb_v2394; }
    { const char * tb_v2395 = "            addr = align(addr, 0x400000)\n"; *(const char * *)tb_grow(v_lines) = tb_v2395; }
    { const char * tb_v2396 = "            syms_extra[\"tb_heap_area\"] = addr\n"; *(const char * *)tb_grow(v_lines) = tb_v2396; }
    { const char * tb_v2397 = "        for k in order:\n"; *(const char * *)tb_grow(v_lines) = tb_v2397; }
    { const char * tb_v2398 = "            if group(secs[k]) != g:\n"; *(const char * *)tb_grow(v_lines) = tb_v2398; }
    { const char * tb_v2399 = "                continue\n"; *(const char * *)tb_grow(v_lines) = tb_v2399; }
    { const char * tb_v2400 = "            s = secs[k]\n"; *(const char * *)tb_grow(v_lines) = tb_v2400; }
    { const char * tb_v2401 = "            addr = align(addr, s[\"align\"])\n"; *(const char * *)tb_grow(v_lines) = tb_v2401; }
    { const char * tb_v2402 = "            s[\"addr\"] = addr\n"; *(const char * *)tb_grow(v_lines) = tb_v2402; }
    { const char * tb_v2403 = "            addr += s[\"size\"]\n"; *(const char * *)tb_grow(v_lines) = tb_v2403; }
    { const char * tb_v2404 = "        if g == 5:\n"; *(const char * *)tb_grow(v_lines) = tb_v2404; }
    { const char * tb_v2405 = "            placed[\"common\"] = addr      # COMMON — сразу за .bss\n"; *(const char * *)tb_grow(v_lines) = tb_v2405; }
    { const char * tb_v2406 = "            secs_common_start = addr\n"; *(const char * *)tb_grow(v_lines) = tb_v2406; }
    { const char * tb_v2407 = "    # символы\n"; *(const char * *)tb_grow(v_lines) = tb_v2407; }
    { const char * tb_v2408 = "    symtab = next((s for s in secs if s[\"type\"] == SHT_SYMTAB), None)\n"; *(const char * *)tb_grow(v_lines) = tb_v2408; }
    { const char * tb_v2409 = "    if symtab is None:\n"; *(const char * *)tb_grow(v_lines) = tb_v2409; }
    { const char * tb_v2410 = "        fail(\"в файле нет таблицы символов\")\n"; *(const char * *)tb_grow(v_lines) = tb_v2410; }
    { const char * tb_v2411 = "    sstr = secs[symtab[\"link\"]]\n"; *(const char * *)tb_grow(v_lines) = tb_v2411; }
    { const char * tb_v2412 = "    nsym = symtab[\"size\"] // 16\n"; *(const char * *)tb_grow(v_lines) = tb_v2412; }
    { const char * tb_v2413 = "    values = []\n"; *(const char * *)tb_grow(v_lines) = tb_v2413; }
    { const char * tb_v2414 = "    common_at = secs_common_start\n"; *(const char * *)tb_grow(v_lines) = tb_v2414; }
    { const char * tb_v2415 = "    for k in range(nsym):\n"; *(const char * *)tb_grow(v_lines) = tb_v2415; }
    { const char * tb_v2416 = "        st_name, st_value, st_size, st_info, st_other, st_shndx = struct.unpack_from(\"<IIIBBH\", data, symtab[\"off\"] + k * 16)\n"; *(const char * *)tb_grow(v_lines) = tb_v2416; }
    { const char * tb_v2417 = "        end = data.index(b\"\\0\", sstr[\"off\"] + st_name)\n"; *(const char * *)tb_grow(v_lines) = tb_v2417; }
    { const char * tb_v2418 = "        name = data[sstr[\"off\"] + st_name:end].decode()\n"; *(const char * *)tb_grow(v_lines) = tb_v2418; }
    { const char * tb_v2419 = "        if st_shndx == SHN_UNDEF:\n"; *(const char * *)tb_grow(v_lines) = tb_v2419; }
    { const char * tb_v2420 = "            if k == 0:\n"; *(const char * *)tb_grow(v_lines) = tb_v2420; }
    { const char * tb_v2421 = "                v = 0\n"; *(const char * *)tb_grow(v_lines) = tb_v2421; }
    { const char * tb_v2422 = "            elif name in syms_extra:\n"; *(const char * *)tb_grow(v_lines) = tb_v2422; }
    { const char * tb_v2423 = "                v = syms_extra[name]\n"; *(const char * *)tb_grow(v_lines) = tb_v2423; }
    { const char * tb_v2424 = "            else:\n"; *(const char * *)tb_grow(v_lines) = tb_v2424; }
    { const char * tb_v2425 = "                fail(\"нет символа: \" + name)\n"; *(const char * *)tb_grow(v_lines) = tb_v2425; }
    { const char * tb_v2426 = "        elif st_shndx == SHN_ABS:\n"; *(const char * *)tb_grow(v_lines) = tb_v2426; }
    { const char * tb_v2427 = "            v = st_value\n"; *(const char * *)tb_grow(v_lines) = tb_v2427; }
    { const char * tb_v2428 = "        elif st_shndx == SHN_COMMON:\n"; *(const char * *)tb_grow(v_lines) = tb_v2428; }
    { const char * tb_v2429 = "            common_at = align(common_at, max(st_value, 1))\n"; *(const char * *)tb_grow(v_lines) = tb_v2429; }
    { const char * tb_v2430 = "            v = common_at\n"; *(const char * *)tb_grow(v_lines) = tb_v2430; }
    { const char * tb_v2431 = "            common_at += st_size\n"; *(const char * *)tb_grow(v_lines) = tb_v2431; }
    { const char * tb_v2432 = "        elif secs[st_shndx][\"addr\"] is None:\n"; *(const char * *)tb_grow(v_lines) = tb_v2432; }
    { const char * tb_v2433 = "            v = 0\n"; *(const char * *)tb_grow(v_lines) = tb_v2433; }
    { const char * tb_v2434 = "        else:\n"; *(const char * *)tb_grow(v_lines) = tb_v2434; }
    { const char * tb_v2435 = "            v = secs[st_shndx][\"addr\"] + st_value\n"; *(const char * *)tb_grow(v_lines) = tb_v2435; }
    { const char * tb_v2436 = "        values.append((name, v))\n"; *(const char * *)tb_grow(v_lines) = tb_v2436; }
    { const char * tb_v2437 = "    if common_at > secs_common_start:\n"; *(const char * *)tb_grow(v_lines) = tb_v2437; }
    { const char * tb_v2438 = "        if syms_extra.get(\"tb_heap_area\", 0) < common_at:\n"; *(const char * *)tb_grow(v_lines) = tb_v2438; }
    { const char * tb_v2439 = "            fail(\"COMMON налез на кучу\")\n"; *(const char * *)tb_grow(v_lines) = tb_v2439; }
    { const char * tb_v2440 = "    # образ памяти от 1 МБ до конца .bss (куча не пишется в файл)\n"; *(const char * *)tb_grow(v_lines) = tb_v2440; }
    { const char * tb_v2441 = "    heap = syms_extra[\"tb_heap_area\"]\n"; *(const char * *)tb_grow(v_lines) = tb_v2441; }
    { const char * tb_v2442 = "    end_all = max([secs[k][\"addr\"] + secs[k][\"size\"] for k in order] + [heap])\n"; *(const char * *)tb_grow(v_lines) = tb_v2442; }
    { const char * tb_v2443 = "    kernel_end = align(end_all, 4096)\n"; *(const char * *)tb_grow(v_lines) = tb_v2443; }
    { const char * tb_v2444 = "    for idx, (name, v) in enumerate(values):\n"; *(const char * *)tb_grow(v_lines) = tb_v2444; }
    { const char * tb_v2445 = "        if name == \"tb_kernel_end\":\n"; *(const char * *)tb_grow(v_lines) = tb_v2445; }
    { const char * tb_v2446 = "            values[idx] = (name, kernel_end)\n"; *(const char * *)tb_grow(v_lines) = tb_v2446; }
    { const char * tb_v2447 = "    file_end = max([secs[k][\"addr\"] + secs[k][\"size\"] for k in order if secs[k][\"type\"] == SHT_PROGBITS] + [0x100000])\n"; *(const char * *)tb_grow(v_lines) = tb_v2447; }
    { const char * tb_v2448 = "    image = bytearray(file_end - 0x100000)\n"; *(const char * *)tb_grow(v_lines) = tb_v2448; }
    { const char * tb_v2449 = "    for k in order:\n"; *(const char * *)tb_grow(v_lines) = tb_v2449; }
    { const char * tb_v2450 = "        s = secs[k]\n"; *(const char * *)tb_grow(v_lines) = tb_v2450; }
    { const char * tb_v2451 = "        if s[\"type\"] == SHT_PROGBITS:\n"; *(const char * *)tb_grow(v_lines) = tb_v2451; }
